<?php
declare(strict_types=1);
require_once __DIR__.'/ResearchExecutionTest.php';
use DigiForge\Portal\{CommercialResearchPanel,ResearchExecutionPanel};
final class ResearchExecutionPanelTest extends WP_UnitTestCase {
 use PhotoWorkflowFixtureIsolation {tearDown as private restoreFixture;}
 private array $floors=[];
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();ShopAccessFixture::reset();$this->capturePhotoFixtureState();global $wpdb;foreach(['jobs','ai_tasks','ai_models']as $m){$t=DigiForge\Database\Tables::{$m}();$this->floors[$t]=(int)$wpdb->get_var('SELECT COALESCE(MAX(id),0) FROM '.$t);}wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['personalized_pod'],['manage_digiforge_pod','manage_digiforge_research','manage_digiforge_ai']);DigiForge\Core\Settings::protectProduction();$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');}
 protected function tearDown():void {global $wpdb;foreach(array_reverse($this->floors,true)as $t=>$id)$wpdb->query('DELETE FROM '.$t.' WHERE id>'.(int)$id);$this->restoreFixture();}
 private function fixture():array {return (new ReflectionMethod(ResearchExecutionTest::class,'boot'))->invoke(new ResearchExecutionTest());}
 private function html($service):string {ob_start();(new ResearchExecutionPanel($service))->render('personalized_pod');return ob_get_clean();}
 private function post(array $source,array $run):array {return ['operation'=>'research_queue_enqueue','shop_key'=>'personalized_pod','confirm'=>'1','sources'=>[$source['hash']],'maximum'=>'1','freshness_days'=>'30','per_task_ceiling'=>'0.020000','currency'=>'USD','request_key'=>'panel-'.wp_generate_uuid4(),'run_id'=>$run['run_id'],'started_at'=>$run['started_at']];}
 public function testNormalPortalFormsDriveDeferredResearchWithoutPastedJson():void {
  [$s,$source,$t,$run]=$this->fixture();(new ReflectionMethod(ResearchExecutionTest::class,'quote'))->invoke(new ResearchExecutionTest(),$s,$source,$run);$panel=new CommercialResearchPanel($s);$html=$this->html($s);self::assertStringContainsString('name="sources[]"',$html);self::assertStringContainsString('research_queue_enqueue',$html);self::assertStringNotContainsString('<textarea',$html);self::assertStringContainsString('name="_wpnonce"',$html);
  $queued=$panel->process($this->post($source,$run));self::assertNotWPError($queued);$job=$queued['research_job'];$p=['operation'=>'research_queue_step','shop_key'=>'personalized_pod','confirm'=>'1','research_job_id'=>(string)$job['id'],'expected_event'=>$job['event_sha256']];$waiting=$panel->process($p);self::assertNotWPError($waiting);self::assertSame('WAITING',$waiting['research_job']['state']);self::assertStringContainsString('Check background result',$this->html($s));self::assertWPError($panel->process($p));$p['expected_event']=$waiting['research_job']['event_sha256'];$done=$panel->process($p);self::assertNotWPError($done);self::assertSame('AWAITING_REVIEW',$done['research_job']['state']);self::assertStringContainsString('Open three concepts',$this->html($s));self::assertStringContainsString('SYNTHETIC OFFLINE SIMULATION',$this->html($s));self::assertSame(1,$t->starts());
 }
 public function testPreStageRecoveryIsAvailableInNormalPortalWithExpiredOnlyGuard():void {
  [$s,$source,$t,$run]=$this->fixture();$panel=new CommercialResearchPanel($s);$queued=$panel->process($this->post($source,$run));self::assertNotWPError($queued);$job=$queued['research_job'];self::assertStringContainsString('research_queue_recover',$this->html($s));$post=['operation'=>'research_queue_recover','shop_key'=>'personalized_pod','confirm'=>'1','research_job_id'=>(string)$job['id'],'expected_event'=>$job['event_sha256']];self::assertWPError($panel->process($post),'Fresh queued intent is not an expired worker.');$q=new DigiForge\Queue\JobRepository();self::assertTrue($q->acquireLease($job['id'],'synthetic_portal_recovery',1));self::assertTrue($q->start($job['id'],'synthetic_portal_recovery'));global $wpdb;$wpdb->update(DigiForge\Database\Tables::jobs(),['lease_expires_at'=>gmdate('Y-m-d H:i:s',time()-10)],['id'=>$job['id']]);$recovered=$panel->process($post);self::assertNotWPError($recovered);self::assertSame('UNKNOWN',$recovered['research_job']['state']);self::assertSame(0,$t->starts());
 }
 public function testQueuedFormsAndResultLinksRetainMountedPortalPage():void {
  [$s,$source,$t,$run]=$this->fixture();$id=self::factory()->post->create(['post_type'=>'page','post_status'=>'publish','post_title'=>'Shop 2 mounted portal']);$url=get_permalink($id);$this->go_to($url);$html=$this->html($s);self::assertStringContainsString('name="return_url" value="'.esc_attr($url).'"',$html);$method=new ReflectionMethod(ResearchExecutionTest::class,'quote');$method->invoke(new ResearchExecutionTest(),$s,$source,$run);$panel=new CommercialResearchPanel($s);$j=$panel->process($this->post($source,$run))['research_job'];foreach([1,2]as $step){$j=$panel->process(['operation'=>'research_queue_step','shop_key'=>'personalized_pod','confirm'=>'1','research_job_id'=>(string)$j['id'],'expected_event'=>$j['event_sha256']])['research_job'];}$expected=add_query_arg(['df_view'=>'research','df_shop'=>'personalized_pod','df_research_version'=>$j['results'][0]['result_sha256']],$url);self::assertStringContainsString(esc_url($expected).'#df-commercial-research',$this->html($s));
 }
 public function testPortalConfirmationScopeAndRevocationAreNotOptional():void {
  [$s,$source,$t,$run]=$this->fixture();$panel=new CommercialResearchPanel($s);$p=$this->post($source,$run);unset($p['confirm']);self::assertWPError($panel->process($p));$p=$this->post($source,$run);$p['shop_key']='digital';self::assertWPError($panel->process($p));wp_get_current_user()->add_cap('manage_digiforge_ai',false);self::assertWPError($panel->process($this->post($source,$run)));self::assertSame(0,$t->starts());
 }
}
